mapper.update:
UPDATE herb_atlas
SET deleted = 1,
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 0

mapper.select:
SELECT COUNT(1)
FROM herb_atlas
WHERE species_id = #{speciesId}
  AND image_name = #{imageName}
  AND deleted = 0
LIMIT 1

