SELECT

FROM herb_atlas a
LEFT JOIN herb_species s ON s.id = a.species_id AND s.deleted = 0

    a.deleted = 0

        AND a.species_id = #{query.speciesId}


        AND (
            a.atlas_code LIKE CONCAT('%', #{query.keyword}, '%')
            OR a.image_name LIKE CONCAT('%', #{query.keyword}, '%')
            OR a.description LIKE CONCAT('%', #{query.keyword}, '%')
            OR s.herb_name LIKE CONCAT('%', #{query.keyword}, '%')
        )


        AND a.image_type = #{query.imageType}


        AND a.growth_stage = #{query.growthStage}


        AND a.status = #{query.status}


ORDER BY a.create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT a.id, a.species_id, s.herb_name, a.atlas_code, a.image_url, a.image_name, a.image_type, a.growth_stage, a.medicinal_part, a.source, a.description, a.status, a.create_time, a.update_time, a.deleted FROM herb_atlas a LEFT JOIN herb_species s ON s.id = a.species_id AND s.deleted = 0 WHERE a.deleted = 0 AND a.status = 1
AND a.species_id = #{speciesId}
ORDER BY a.id ASC
